"""CCDV-F part A: Domain 1 (Agents and Workflows) and Domain 2 (Applications and Integration).

Written against the Claude Certified Developer - Foundations exam guide (version 1.0, effective
July 2026; Domain 1 weight 14.7%, Domain 2 weight 33.1%) and verified in October 2026 against the
current Claude API, Agent SDK, Managed Agents and Claude Code documentation. Part B
(data/ccdv_b.py) owns the other categories. IDs here stay below 1000 so they never collide with
part B.
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


